window.__votdWeek && window.__votdWeek({"week":"2029-04-30","reading":"Doctrine and Covenants 41–44","days":[{"d":"2029-04-30","ref":"D&C 41:5","b":"D&C","c":41,"v":5,"he":"הַמְקַבֵּל תּוֹרָתִי וְעֹשֶׂה אֹתָהּ הוּא תַלְמִידִי וְהָאֹמֵר כִּי מְקַבֵּל הוּא אֹתָהּ וְלֹא יַעֲשֶׂנָּה אֵינֶנּוּ תַלְמִידִי וִיגֹרַשׁ מִקִּרְבְּכֶם׃","en":"He that receiveth my law and doeth it, the same is my disciple; and he that saith he receiveth it and doeth it not, the same is not my disciple, and shall be cast out from among you;"},{"d":"2029-05-01","ref":"D&C 41:6","b":"D&C","c":41,"v":6,"he":"כִּי לֹא נָכוֹן לָתֵת אֶת־אֲשֶׁר לִבְנֵי הַמַּלְכוּת לַאֲשֶׁר אֵינָם רְאוּיִים אוֹ לַכְּלָבִים אוֹ לְהַשְׁלִיךְ פְּנִינִים לִפְנֵי הַחֲזִירִים׃","en":"For it is not meet that the things which belong to the children of the kingdom should be given to them that are not worthy, or to dogs, or the pearls to be cast before swine."},{"d":"2029-05-02","ref":"D&C 42:30","b":"D&C","c":42,"v":30,"he":"וְהִנֵּה תִזְכֹּר אֶת־הָעֲנִיִּים וְהִקְדַּשְׁתָּ מֵרְכוּשְׁךָ לְתָמְכָם אֶת־אֲשֶׁר תּוּכַל לָתֵת לָהֶם בִּבְרִית וּכְתָב אֲשֶׁר לֹא יוּפַר׃","en":"And behold, thou wilt remember the poor, and consecrate of thy properties for their support that which thou hast to impart unto them, with a covenant and a deed which cannot be broken."},{"d":"2029-05-03","ref":"D&C 42:48","b":"D&C","c":42,"v":48,"he":"וְעוֹד יִהְיֶה הַמַּאֲמִין בִּי לְהֵרָפֵא וְאֵינֶנּוּ מְמֻנֶּה לָמוּת יֵרָפֵא׃","en":"And again, it shall come to pass that he that hath faith in me to be healed, and is not appointed unto death, shall be healed."},{"d":"2029-05-04","ref":"D&C 43:7","b":"D&C","c":43,"v":7,"he":"כִּי אָמֵן אֲנִי אֹמֵר לָכֶם הַנִּסְמָךְ מֵאִתִּי יָבוֹא בַשַּׁעַר וְיִסָּמֵךְ כַּאֲשֶׁר אָמַרְתִּי לָכֶם מִלְּפָנִים לְלַמֵּד הַחֲזוֹנוֹת אֲשֶׁר קִבַּלְתֶּם וּתְקַבְּלוּ בְּיַד אֲשֶׁר מִנִּיתִי׃","en":"For verily I say unto you, that he that is ordained of me shall come in at the gate and be ordained as I have told you before, to teach those revelations which you have received and shall receive through him whom I have appointed."},{"d":"2029-05-05","ref":"D&C 43:31","b":"D&C","c":43,"v":31,"he":"כִּי הַשָּׂטָן יֵאָסֵר וּבְהֻתְּרוֹ עוֹד יִמְלֹךְ רַק לַמִּצְעָר וְאָז יָבוֹא קֵץ הָאָרֶץ׃","en":"For Satan shall be bound, and when he is loosed again he shall only reign for a little season, and then cometh the end of the earth."},{"d":"2029-05-06","ref":"D&C 44:5","b":"D&C","c":44,"v":5,"he":"לְמַעַן לֹא יִהְיֶה לְאֹיְבֵיכֶם כֹּחַ עֲלֵיכֶם לְמַעַן תִּשָּׁמְרוּ בְּכׇל דָּבָר לְמַעַן תּוּכְלוּ לִשְׁמֹר חֻקּוֹתַי לְמַעַן יִנָּתֵק כׇּל מוֹסֵר אֲשֶׁר מְבַקֵּשׁ הָאוֹיֵב לְהַשְׁמִיד עַמִּי׃","en":"That your enemies may not have power over you; that you may be preserved in all things; that you may be enabled to keep my laws; that every bond may be broken wherewith the enemy seeketh to destroy my people."}]});
